public static (int, int) RowAndColumn(int rowCount, int columnCount, int index, ArrangementEnum arrangement)
        {
            if (arrangement == ArrangementEnum.Normal)
            {
                int row = index / columnCount + 1;

                if (index % columnCount == 0)
                {
                    row--;
                }

                int column = index - ((row - 1) * columnCount);

                return (row, column);
            }
            else if (arrangement == ArrangementEnum.Snake)
            {
                int row = index / columnCount + 1;

                if (index % columnCount == 0)
                {
                    row--;
                }

                int column;
                if (row % 2 == 0)
                {
                    column = index - ((row - 1) * columnCount);
                }
                else
                {
                    column = columnCount - (row * columnCount - index);
                }

                return (row, column);
            }

            return (0, 0);
        }

public static int GetIndex(int index, int columnCount = 1, int rowCount = 1, ArrangementEnum arrangement = ArrangementEnum.Normal, WorkOrderEnum workOrder = WorkOrderEnum.LeftDownToRight)
        {
            int rowIndex = (index - 1) / columnCount + 1;

            int columnIndex = index - (rowIndex - 1) * columnCount;

            int realIndex = 0;

            if (workOrder == WorkOrderEnum.LeftDownToRight)
            {
                if (arrangement == ArrangementEnum.Normal)
                {
                    realIndex = index;
                }
                else
                {
                    if (rowIndex % 2 == 0)
                    {
                        realIndex = rowIndex * columnCount - index + (rowIndex - 1) * columnCount + 1;
                    }
                    else
                    {
                        realIndex = index;
                    }
                }
            }
            else if (workOrder == WorkOrderEnum.LeftDownToUp)
            {
                if (arrangement == ArrangementEnum.Normal)
                {
                    realIndex = rowCount * (columnIndex - 1) + rowIndex;
                }
                else
                {
                    if (columnIndex % 2 == 0)
                    {
                        realIndex = rowCount * (columnIndex - 1) + rowIndex;

                        realIndex = realIndex - rowIndex + rowCount - rowIndex + 1;
                    }
                    else
                    {
                        realIndex = rowCount * (columnIndex - 1) + rowIndex;
                    }
                }
            }
            else if (workOrder == WorkOrderEnum.LeftUpToRight)
            {
                if (arrangement == ArrangementEnum.Normal)
                {
                    realIndex = (rowCount - rowIndex) * columnCount + columnIndex;
                }
                else
                {
                    if ((rowCount - rowIndex) % 2 == 0)
                    {
                        realIndex = (rowCount - rowIndex) * columnCount + columnIndex;
                    }
                    else
                    {
                        realIndex = (rowCount - rowIndex) * columnCount + columnIndex;
                        realIndex = realIndex - columnIndex + columnCount - columnIndex + 1;
                    }
                }
            }
            else if (workOrder == WorkOrderEnum.LeftUpToDown)
            {
                if (arrangement == ArrangementEnum.Normal)
                {
                    realIndex = rowCount * (columnIndex - 1) + (rowCount - rowIndex + 1);
                }
                else
                {
                    if ((columnCount - columnIndex + 1) % 2 == 0)
                    {
                        realIndex = rowCount * (columnIndex - 1) + rowIndex;
                    }
                    else
                    {
                        realIndex = rowCount * (columnIndex - 1) + (rowCount - rowIndex + 1);
                    }
                }
            }
            else if (workOrder == WorkOrderEnum.RightDownToUp)
            {
                if (arrangement == ArrangementEnum.Normal)
                {
                    realIndex = rowCount * (columnCount - columnIndex) + rowIndex;
                }
                else
                {
                    if (columnIndex % 2 == 0)
                    {
                        realIndex = rowCount * (columnCount - columnIndex) + rowIndex;
                    }
                    else
                    {
                        realIndex = rowCount * (columnCount - columnIndex) + rowIndex;
                    }
                }
            }
            else if (workOrder == WorkOrderEnum.RightDownToLeft)
            {
                if (arrangement == ArrangementEnum.Normal)
                {
                    realIndex = columnCount * (rowIndex - 1) + columnCount - columnIndex + 1;
                }
                else
                {
                    if ((rowCount - rowIndex + 1) % 2 == 0)
                    {
                        realIndex = columnCount * (rowIndex - 1) + columnCount - columnIndex + 1;
                    }
                    else
                    {
                        realIndex = columnCount * (rowIndex - 1) + columnCount - columnIndex + 1;
                        realIndex = columnCount * (rowIndex - 1) + columnIndex;
                    }
                }
            }
            else if (workOrder == WorkOrderEnum.RightUpToDown)
            {
                if (arrangement == ArrangementEnum.Normal)
                {
                    realIndex = rowCount * (columnCount - columnIndex) + rowCount - rowIndex + 1;
                }
                else
                {
                    if ((columnCount - columnIndex + 1) % 2 == 0)
                    {
                        realIndex = rowCount * (columnCount - columnIndex) + rowIndex;
                    }
                    else
                    {
                        realIndex = rowCount * (columnCount - columnIndex) + rowIndex;
                        realIndex = rowCount * (columnCount - columnIndex) + rowCount - rowIndex + 1;
                    }
                }
            }
            else if (workOrder == WorkOrderEnum.RightUpToLeft)
            {
                if (arrangement == ArrangementEnum.Normal)
                {
                    realIndex = rowCount * columnCount - index + 1;
                }
                else
                {
                    if ((rowCount - rowIndex) % 2 == 0)
                    {
                        realIndex = rowCount * columnCount - index + 1;
                    }
                    else
                    {
                        realIndex = columnCount * (rowCount - rowIndex) + columnIndex;
                    }
                }
            }
            else
            {
                throw new Exception("顺序出现问题，请联系软件人员");
            }

            return realIndex;
        }

public static void CreateMatterCoordinate(BaseMatter baseMatter, GeneralCoordinateSystem upperCoordinateSystem, ElementCoordinate elementCoordinate)
        {
            baseMatter.CoordinateSystem = new GeneralCoordinateSystem(
                baseMatter.Name,
                CoordinateSystemTypeEnum.General,
                upperCoordinateSystem);

            baseMatter.CoordinateSystem.Init(elementCoordinate);
        }

public static void ModifyMatter(TransportUnit transportUnit, OtherConfig config)
        {
            try
            {
                if (ProductConfiguration.GetInstance().TransportUnitConfig.IsOppositeSex)
                {
                    foreach (Substrate substrate in transportUnit.Substrates)
                    {
                        foreach (Module module in substrate.Modules)
                        {
                            foreach (BondPosition bondPosition in module.BondPositions)
                            {
                                bondPosition.MatterProductState = bondPosition.OppositeSex.MatterProductState;
                            }
                        }
                    }
                }
                else
                {
                    if (ProductConfiguration.GetInstance().TransportUnitConfig.LagerNumber)
                    {
                        foreach (Substrate substrate in transportUnit.Substrates)
                        {
                            foreach (Module module in substrate.Modules)
                            {
                                module.SubstrateNum = substrate.Index;
                                foreach (BondPosition bondPosition in module.BondPositions)
                                {
                                    bondPosition.SubstrateNum = substrate.Index;
                                    bondPosition.ModuleNum = module.Index;

                                    List<MatterProductInformationMin> MatterProductInformationMins = config.MatterProductInfoMax[substrate.Index - 1][module.Index - 1];

                                    MatterProductInformationMin matterProductInformationMin = MatterProductInformationMins.Find(it => it.BondPositionName == bondPosition.Name);
                                    bondPosition.MatterProductState = matterProductInformationMin.MatterProductState;
                                }
                            }
                        }
                    }
                    else
                    {
                        foreach (Substrate substrate in transportUnit.Substrates)
                        {
                            foreach (Module module in substrate.Modules)
                            {
                                module.SubstrateNum = substrate.Index;
                                foreach (BondPosition bondPosition in module.BondPositions)
                                {
                                    bondPosition.SubstrateNum = substrate.Index;
                                    bondPosition.ModuleNum = module.Index;
                                    if (config.MatterProductInfo.Exists(
                                            it => it.SubstrateIndex == substrate.Index && it.ModuleIndex == module.Index
                                                  && it.BondPositionName == bondPosition.Name))
                                    {
                                        MatterProductInformation matterProductInformation = config.MatterProductInfo.Find(
                                            it => it.SubstrateIndex == substrate.Index && it.ModuleIndex == module.Index
                                                  && it.BondPositionName == bondPosition.Name);
                                        bondPosition.MatterProductState = matterProductInformation.MatterProductState;
                                    }
                                }
                            }
                        }
                    }
                }
            }
            catch (Exception e)
            {
                config.ClearInformation();
                ProductConfiguration.GetInstance().Save();
            }
        }

public Substrate(int index, GeneralCoordinateSystem upperCoordinateSystem)
        {
            this.MatterTypeEnum = EntityTypeEnum.Substrate;
            
            this.Index = index;

            this.WorkIndex = TuService.GetIndex(
                index,
                this.SubstrateConfig.ColumnCount,
                this.SubstrateConfig.RowCount,
                this.SubstrateConfig.Arrangement,
                this.SubstrateConfig.WorkOrderEnum);

            this.Name = $"基板{index}";

            this.BaseInfo = new SubstrateInfo();
            
            TuService.CreateMatterCoordinate(
                this,
                upperCoordinateSystem,
                this.SubstrateConfig.ElementCoordinates[index - 1]);

            this.CreateModule();
        }

public Substrate(int index, GeneralCoordinateSystem upperCoordinateSystem, OppositeSex opposite)
        {
            this.MatterTypeEnum = EntityTypeEnum.Substrate;

            this.OppositeSex = opposite;

            this.Index = index;

            this.WorkIndex = index;

            this.Name = opposite.Name;

            this.BaseInfo = new SubstrateInfo();

            TuService.CreateMatterCoordinate(this, upperCoordinateSystem, opposite.ElementCoordinate);

            this.InitModuleByOppositeSex();
        }

public void CreateModule()
        {
            ModuleConfig moduleConfig = ProductConfiguration.GetInstance().ModuleConfig;

            if (!moduleConfig.IsMultiple)
            {
                moduleConfig.Count = 1;
                moduleConfig.ColumnCount = 1;
                moduleConfig.RowCount = 1;
                moduleConfig.ElementCoordinates.Clear();
                moduleConfig.ElementCoordinates.Add(new ElementCoordinate());
            }

            // 如果没有，初始化一个
            if (moduleConfig.ElementCoordinates.Count == 0)
            {
                moduleConfig.ElementCoordinates.Add(new ElementCoordinate());
            }

            if (moduleConfig.IsAssistanceDistanceByInput)
            {
                ElementCoordinate elementCoordinateFirst = moduleConfig.ElementCoordinates[0];
                moduleConfig.ElementCoordinates.Clear();

                for (int i = 0; i < moduleConfig.RowCount; i++)
                {
                    for (int j = 0; j < moduleConfig.ColumnCount; j++)
                    {
                        // Z轴的位置是跟随TU的，如果需要设置，需要到单独的测高界面
                        ElementCoordinate elementCoordinate = new ElementCoordinate();
                        elementCoordinate.Point = new AKRSPoint3D(
                            elementCoordinateFirst.Point.X + moduleConfig.ColumnSpacing * j,
                            elementCoordinateFirst.Point.Y + moduleConfig.RowSpacing * i,
                            elementCoordinateFirst.Point.Z);
                        elementCoordinate.Degree = 0;
                        moduleConfig.ElementCoordinates.Add(elementCoordinate);
                    }
                }
            }

            for (int i = 0; i < moduleConfig.Count; i++)
            {
                Module module = new Module(
                    i + 1,
                    this.CoordinateSystem);

                // 判断行列数
                if (moduleConfig.Multiplication == MultiplicationEnum.Matrix)
                {
                    (module.RowIndex, module.ColumnIndex) = TuService.RowAndColumn(
                        moduleConfig.RowCount,
                        moduleConfig.ColumnCount,
                        i + 1,
                        moduleConfig.Arrangement);
                }

                this.Modules.Add(module);
            }
        }

private void InitModuleByOppositeSex()
        {
            this.Modules.Clear();
            for (int i = 0; i < this.OppositeSex.DownConfigs.Count; i++)
            {
                Module module = new Module(i + 1, this.CoordinateSystem, this.OppositeSex.DownConfigs[i]);
                this.Modules.Add(module);
            }
        }

public void Refresh(int index, GeneralCoordinateSystem upperCoordinateSystem)
        {
            this.Index = index;

            if (this.OppositeSex != null)
            {
                TuService.CreateMatterCoordinate(this, upperCoordinateSystem, this.OppositeSex.ElementCoordinate);
            }
            else
            {
                this.WorkIndex = TuService.GetIndex(
                    index,
                    this.SubstrateConfig.ColumnCount,
                    this.SubstrateConfig.RowCount,
                    this.SubstrateConfig.Arrangement,
                    this.SubstrateConfig.WorkOrderEnum);

                TuService.CreateMatterCoordinate(
                    this,
                    upperCoordinateSystem,
                    this.SubstrateConfig.ElementCoordinates[index - 1]);
            }

            for (int i = 0; i < this.Modules.Count; i++)
            {
                this.Modules[i].Refresh(i + 1, this.CoordinateSystem);
            }
        }

public Module(int index, GeneralCoordinateSystem upperCoordinateSystem)
        {
            this.MatterTypeEnum = EntityTypeEnum.Module;

            this.Index = index;

            this.WorkIndex = TuService.GetIndex(
                index,
                this.ModuleConfig.ColumnCount,
                this.ModuleConfig.RowCount,
                this.ModuleConfig.Arrangement,
                this.ModuleConfig.WorkOrderEnum);
            
            this.Name = $"基岛{index}";

            TuService.CreateMatterCoordinate(
                this,
                upperCoordinateSystem,
                this.ModuleConfig.ElementCoordinates[index - 1]);

            this.BaseInfo = new ModuleInfo();

            this.CreateBondPosition();
        }

public Module(int index, GeneralCoordinateSystem upperCoordinateSystem, OppositeSex oppositeSex)
        {
            this.MatterTypeEnum = EntityTypeEnum.Module;

            this.OppositeSex = oppositeSex;

            this.Index = index;

            this.WorkIndex = index;

            this.Name = oppositeSex.Name;

            TuService.CreateMatterCoordinate(this, upperCoordinateSystem, oppositeSex.ElementCoordinate);

            this.BaseInfo = new ModuleInfo();

            this.CreateBondPositionByOppositeSex();
        }

public void CreateBondPosition()
        {
            BondPositionConfig bondPositionConfig = ProductConfiguration.GetInstance().BondPositionConfig;

            this.BondPositions.Clear();


            for (int i = 0; i < bondPositionConfig.SingleBpPositionConfigList.Count; i++)
            {
                BondPosition bondPosition = new BondPosition(
                    bondPositionConfig.SingleBpPositionConfigList[i].Name,
                    i + 1,
                    this.CoordinateSystem);

                this.BondPositions.Add(bondPosition);
            }
        }

public void CreateBondPositionByOppositeSex()
        {
            this.BondPositions.Clear();

            for (int i = 0; i < this.OppositeSex.DownConfigs.Count; i++)
            {
                BondPosition bondPosition = new BondPosition(
                    i + 1,
                    this.CoordinateSystem,
                    this.OppositeSex.DownConfigs[i]);

                this.BondPositions.Add(bondPosition);
            }
        }

public void Refresh(int index, GeneralCoordinateSystem upperCoordinateSystem)
        {
            this.Index = index;

            if (this.OppositeSex != null)
            {
                TuService.CreateMatterCoordinate(this, upperCoordinateSystem, this.OppositeSex.ElementCoordinate);
            }
            else
            {
                this.WorkIndex = TuService.GetIndex(
                    index,
                    this.ModuleConfig.ColumnCount,
                    this.ModuleConfig.RowCount,
                    this.ModuleConfig.Arrangement,
                    this.ModuleConfig.WorkOrderEnum);
                TuService.CreateMatterCoordinate(
                    this,
                    upperCoordinateSystem,
                    this.ModuleConfig.ElementCoordinates[index - 1]);
            }

            foreach (BondPosition bondPosition in this.BondPositions)
            {
                bondPosition.Refresh(this.CoordinateSystem);
            }
        }

public BondPosition(string name, int index, GeneralCoordinateSystem upperCoordinateSystem)
        {
            this.Name = name;

            this.Index = index;

            this.MatterTypeEnum = EntityTypeEnum.BondPosition;

            this.BaseInfo = new BondPositionInfo();

            TuService.CreateMatterCoordinate(
                this,
                upperCoordinateSystem,
                this.SingleBondPositionConfig.ElementCoordinate);

            this.IsMirror = this.SingleBondPositionConfig.IsMirror;
        }

public BondPosition(int index, GeneralCoordinateSystem upperCoordinateSystem, OppositeSex oppositeSex)
        {
            this.Name = oppositeSex.Name;

            this.OppositeSex = oppositeSex;

            this.Index = index;

            this.MatterTypeEnum = EntityTypeEnum.BondPosition;

            this.BaseInfo = new BondPositionInfo();
            
            TuService.CreateMatterCoordinate(
                this,
                upperCoordinateSystem,
                oppositeSex.ElementCoordinate);

            this.IsMirror = this.OppositeSex.Config.IsMirror;
        }

public void Refresh(GeneralCoordinateSystem upperCoordinateSystem)
        {
            if (this.OppositeSex != null)
            {
                TuService.CreateMatterCoordinate(
                    this,
                    upperCoordinateSystem,
                    this.OppositeSex.ElementCoordinate);
            }
            else
            {
                TuService.CreateMatterCoordinate(
                    this,
                    upperCoordinateSystem,
                    this.SingleBondPositionConfig.ElementCoordinate);
            }
        }

public void RefreshTransportUnit()
        {
            if (this.DispenseSubSectionProgram.TransportUnit != null)
            {
                this.DispenseSubSectionProgram.TransportUnit.Refresh();
            }

            if (this.BondSubSectionProgram.TransportUnit != null)
            {
                this.BondSubSectionProgram.TransportUnit.Refresh();
            }

            if (this.WaitingUnloadSubSectionProgram.TransportUnit != null)
            {
                this.WaitingUnloadSubSectionProgram.TransportUnit.Refresh();
            }
        }

public void Init()
        {
            Task task1 = Task.Factory.StartNew(() => { this.LoadingSubSectionModule.StopMove(); this.LoadingSubSectionModule.BeltInit(); });
            Task task2 = Task.Factory.StartNew(() => { this.DispenseSubSectionModule.StopMove(); this.DispenseSubSectionModule.BeltInit(); });
            Task task3 = Task.Factory.StartNew(() => { this.BondSubSectionModule.StopMove(); this.BondSubSectionModule.BeltInit(); });
            Task task4 = Task.Factory.StartNew(() => { this.WaitingUnloadSubSectionModule.StopMove(); this.WaitingUnloadSubSectionModule.BeltInit(); });
            Task task5 = Task.Factory.StartNew(() => { this.UnloadingSubSectionModule.StopMove(); this.UnloadingSubSectionModule.BeltInit(); });

            Task.WaitAll(task1, task2, task3, task4, task5);
        }
